function UINightCatIToweRewardPopupDialog:OnShow()
    --- @type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local id = comp:GetMaxPassTowerId()
        local index = 0
        local vo = QuestConfMgr:GetInstance():GetQuestVoById(id)
        if vo then
            self.ListContent:MovePanelToItemIndex(checkNumber(vo.storey), 100)
        end
    end))
    return coWait
end

function UINightCatIToweRewardPopupDialog:Awake()
    local argument = self.controller.Argument.parameters
    if argument then
        self._activityId = checkNumber(argument.activityId)  
    end

    if checkNumber(self._activityId) == 0 then
        return
    end

    self:InitData()
    self:FillSelf()
end

function UINightCatIToweRewardPopupDialog:InitData()
    local t = CfUtils.GetIdGroupData(AutoIds.IdSetting2736, self._activityId)
    self._finallyId = t[#t]
    table.remove(t, table.count(t))
    self._allRewardId = t   
end

function UINightCatIToweRewardPopupDialog:FillSelf()
    self.ListContent:InitListView(table.count(self._allRewardId), Bind(self, self.OnGetCellByIndex))

    local scr = CfUtils.GetLuaScr(self.FixedCell, UINightCatIToweRewardNode)
    if scr then
        scr:Refresh(self._finallyId)
    end



end 

function UINightCatIToweRewardPopupDialog:OnGetCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local id = self._allRewardId[index + 1]
    local cell = listView:NewListViewItem("Cell") 

    local scr = CfUtils.GetLuaScr(cell.gameObject, UINightCatIToweRewardNode)
    if scr then
        scr:Refresh(id)
    end

    return cell
end

